import json, random, re
from collections import Counter

DATA_PATH = '/root/autodl-tmp/expert_trajectories/expert_trajectories.jsonl'
data = []
with open(DATA_PATH) as f:
    for line in f:
        line = line.strip()
        if line:
            data.append(json.loads(line))

print(f'Total trajectories: {len(data)}')

def extract_actions(traj):
    actions = []
    for msg in traj['messages']:
        if msg['role'] == 'assistant':
            m = re.search(r'<answer>(.*?)</answer>', msg['content'])
            if m:
                actions.append(m.group(1).strip())
    return actions

def extract_env_responses(traj):
    responses = []
    first_user = True
    for msg in traj['messages']:
        if msg['role'] == 'user':
            if first_user:
                first_user = False
                continue
            responses.append(msg['content'])
    return responses

# move vs put stats
total_move = 0
total_put = 0
move_trajs = 0
for traj in data:
    actions = extract_actions(traj)
    has_move = False
    for a in actions:
        if a.lower().startswith('move'):
            total_move += 1
            has_move = True
        elif a.lower().startswith('put'):
            total_put += 1
    if has_move:
        move_trajs += 1

print(f'move actions: {total_move}, put actions: {total_put}, move ratio: {total_move/(total_move+total_put+1e-9):.1%}')
print(f'Trajs with move: {move_trajs}/{len(data)}')

# Sample 20
random.seed(42)
samples = random.sample(data, min(20, len(data)))
true_pos = 0
false_pos = 0
suspicious = 0
fp_examples = []

print()
print('=== 20 Sample Check ===')
for i, traj in enumerate(samples):
    actions = extract_actions(traj)
    env_responses = extract_env_responses(traj)
    last_action = actions[-1] if actions else 'N/A'
    last_response = env_responses[-1] if env_responses else 'N/A'

    task = ''
    for msg in traj['messages']:
        if msg['role'] == 'user' and 'Your task is to:' in msg['content']:
            task = msg['content'].split('Your task is to:')[-1].strip()[:80]
            break

    last_resp_lower = last_response.lower()
    has_win = 'nothing happens' in last_resp_lower
    uses_move = any(a.lower().startswith('move') for a in actions)

    if has_win:
        status = 'TRUE_POS'
        true_pos += 1
    elif uses_move:
        status = 'SUSPICIOUS'
        suspicious += 1
        fp_examples.append((i, task, last_action, last_response[:120]))
    else:
        status = 'TRUE_POS_IMPL'
        true_pos += 1

    print(f'[{i:2d}] {status:15s} last_act={last_action:45s} task={task[:55]}')

print(f'True positive: {true_pos}, False positive: {false_pos}, Suspicious: {suspicious}')
if fp_examples:
    print('Suspicious examples:')
    for idx, t, la, lr in fp_examples:
        print(f'  #{idx}: task={t}, last_action={la}, last_resp={lr}')

# Full distribution of last env response
print()
print('=== Last env response pattern (full data) ===')
patterns = Counter()
for traj in data:
    env_responses = extract_env_responses(traj)
    if env_responses:
        last = env_responses[-1].lower()
        if 'nothing happens' in last:
            patterns['Nothing happens (win signal)'] += 1
        elif 'you pick up' in last:
            patterns['You pick up...'] += 1
        elif 'you put' in last:
            patterns['You put...'] += 1
        elif 'you arrive' in last:
            patterns['You arrive...'] += 1
        elif 'turned on' in last or 'turned off' in last:
            patterns['turned on/off'] += 1
        elif 'close' in last or 'open' in last:
            patterns['open/close'] += 1
        elif 'cool' in last or 'heat' in last or 'clean' in last:
            patterns['cool/heat/clean'] += 1
        else:
            patterns['other'] += 1
for p, c in patterns.most_common():
    print(f'  {p}: {c} ({c/len(data):.1%})')

print()
print(f'Schema keys: {list(data[0].keys())}')
