import json, re

DATA_PATH = '/root/autodl-tmp/expert_trajectories/expert_trajectories.jsonl'
data = []
with open(DATA_PATH) as f:
    for line in f:
        line = line.strip()
        if line:
            data.append(json.loads(line))

# Check what env responds to 'move' actions specifically
print('=== Env responses to move actions (first 10 examples) ===')
count = 0
for traj in data:
    msgs = traj['messages']
    for j, msg in enumerate(msgs):
        if msg['role'] == 'assistant':
            m = re.search(r'<answer>(.*?)</answer>', msg['content'])
            if m and m.group(1).strip().lower().startswith('move'):
                action = m.group(1).strip()
                # next user message is env response
                if j+1 < len(msgs) and msgs[j+1]['role'] == 'user':
                    resp = msgs[j+1]['content']
                    print(f'  ACTION: {action}')
                    print(f'  RESPONSE: {resp[:150]}')
                    print()
                    count += 1
                    if count >= 10:
                        break
    if count >= 10:
        break

# Check if any move action ever gets 'You put' or 'Nothing happens' response
print('=== Response patterns after move actions (all data) ===')
from collections import Counter
move_resps = Counter()
total_moves = 0
for traj in data:
    msgs = traj['messages']
    for j, msg in enumerate(msgs):
        if msg['role'] == 'assistant':
            m = re.search(r'<answer>(.*?)</answer>', msg['content'])
            if m and m.group(1).strip().lower().startswith('move'):
                total_moves += 1
                if j+1 < len(msgs) and msgs[j+1]['role'] == 'user':
                    resp = msgs[j+1]['content'].lower()
                    if 'you arrive' in resp:
                        move_resps['You arrive...'] += 1
                    elif 'you put' in resp:
                        move_resps['You put...'] += 1
                    elif 'nothing happens' in resp:
                        move_resps['Nothing happens'] += 1
                    elif 'you open' in resp:
                        move_resps['You open...'] += 1
                    else:
                        move_resps['other: ' + resp[:60]] += 1

print(f'Total move actions: {total_moves}')
for p, c in move_resps.most_common():
    print(f'  {p}: {c} ({c/total_moves:.1%})')

# Check task type distribution
print()
print('=== Task type distribution ===')
task_types = Counter()
for traj in data:
    for msg in traj['messages']:
        if msg['role'] == 'user' and 'Your task is to:' in msg['content']:
            task = msg['content'].split('Your task is to:')[-1].strip()
            if 'put' in task.lower():
                task_types['put task'] += 1
            elif 'look at' in task.lower() or 'examine' in task.lower():
                task_types['look/examine task'] += 1
            elif 'clean' in task.lower():
                task_types['clean task'] += 1
            elif 'heat' in task.lower():
                task_types['heat task'] += 1
            elif 'cool' in task.lower():
                task_types['cool task'] += 1
            elif 'find' in task.lower():
                task_types['find task'] += 1
            else:
                task_types['other: ' + task[:40]] += 1
            break
for t, c in task_types.most_common():
    print(f'  {t}: {c} ({c/len(data):.1%})')
